52	\begin{equation}
53	  V_B'(\delta) = -\sum_{j,k} \bigl[(C_0)_{jk} - \mathbf{1}_{j=k}\bigr]\,p_k\,(g_k - \mu_j(\delta))^2.
54	  \label{eq:dVB}
55	\end{equation}
