57	\begin{align*}
58	  V_B'(1) &= \sum_j (1 - \alpha_j)\,p_j\,e_j^2 - \sum_{j \neq k} (C_0)_{jk}\,p_k\,(g_k - \mu_j)^2.
59	\end{align*}
