61	\emph{Key identity.}
62	Since $\mu_j = \sum_k g_k (C_0)_{jk} p_k / q_j$:
63	\begin{equation}
64	  e_j = g_j - \mu_j = \frac{1}{q_j}\sum_{k \neq j} (C_0)_{jk}\,p_k\,(g_j - g_k).
65	  \label{eq:key_identity}
66	\end{equation}
